# AI Office v2.4 Documentation Synchronization Installer
$ErrorActionPreference = "Stop"
$Repository = "E:\AI\AI-Office"
if (-not (Test-Path -LiteralPath $Repository -PathType Container)) { throw "AI Office repository not found." }
Set-Location $Repository
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupDirectory = Join-Path $Repository ("workspace\documentation-backups\v2.4-sync-" + $Timestamp)
New-Item -ItemType Directory -Path $BackupDirectory -Force | Out-Null
function Write-SyncedDocument {
    param(
        [string]$RelativePath,
        [string]$Base64Content
    )

    $Destination = Join-Path $Repository $RelativePath
    $BackupPath = Join-Path $BackupDirectory $RelativePath
    $BackupParent = Split-Path -Parent $BackupPath

    if ($BackupParent -and -not (Test-Path -LiteralPath $BackupParent)) {
        New-Item -ItemType Directory -Path $BackupParent -Force | Out-Null
    }

    if (Test-Path -LiteralPath $Destination -PathType Leaf) {
        Copy-Item -LiteralPath $Destination -Destination $BackupPath -Force
    }

    $Parent = Split-Path -Parent $Destination
    if ($Parent -and -not (Test-Path -LiteralPath $Parent)) {
        New-Item -ItemType Directory -Path $Parent -Force | Out-Null
    }

    [IO.File]::WriteAllBytes(
        $Destination,
        [Convert]::FromBase64String($Base64Content)
    )

    Write-Host "[SYNCED] $RelativePath" -ForegroundColor Green
}
Write-SyncedDocument -RelativePath "README.md" -Base64Content ""
Write-SyncedDocument -RelativePath "PROJECT-STATUS.md" -Base64Content ""
Write-SyncedDocument -RelativePath "ROADMAP.md" -Base64Content ""
Write-SyncedDocument -RelativePath "VISION.md" -Base64Content ""
Write-SyncedDocument -RelativePath "config\project-status.json" -Base64Content ""
$Json = Get-Content -LiteralPath "E:\AI\AI-Office\config\project-status.json" -Raw | ConvertFrom-Json
if ([string]$Json.version -ne "2.4.0") { throw "Project status JSON synchronization failed." }
$Checks = @(
    @{ Path="README.md"; Pattern="v2.4.0" },
    @{ Path="PROJECT-STATUS.md"; Pattern="v2.5 Part A" },
    @{ Path="ROADMAP.md"; Pattern="v3.0" },
    @{ Path="VISION.md"; Pattern="Current Reality" }
)
foreach ($Check in $Checks) {
    $Text = Get-Content -LiteralPath (Join-Path $Repository $Check.Path) -Raw
    if ($Text -notmatch [regex]::Escape($Check.Pattern)) { throw ("Documentation validation failed: " + $Check.Path) }
}
Write-Host ""
Write-Host "AI Office v2.4 project documentation synchronized successfully." -ForegroundColor Green
Write-Host "Historical backup copies were not modified." -ForegroundColor Cyan
Write-Host "Backup created at: $BackupDirectory" -ForegroundColor Cyan